SELECT s.StokHareketID, Format(s.Tarih,"dd.mm.yyyy") AS Tarih, s.UrunID, u.UrunAdi AS Ürün, s.MusteriID, m.AdSoyad AS Müşteri, p.PartiKodu AS Parti, s.HareketTuru AS Hareket, s.Aciklama AS Açıklama, Nz(s.Giris,0) AS Giren, Nz(s.Cikis,0) AS Çıkan, Nz(u.AcilisStok,0)+Nz((SELECT Sum(Nz(x.Giris,0)-Nz(x.Cikis,0)) FROM tbl_StokHareket AS x WHERE x.UrunID=s.UrunID AND x.IptalMi=False AND (x.Tarih<s.Tarih OR (x.Tarih=s.Tarih AND x.StokHareketID<=s.StokHareketID))),0) AS Kalan, Switch(Nz(s.KaynakTipi,"")="PARTI","Üretim",Nz(s.KaynakTipi,"")="TESLIM","Teslim",Nz(s.KaynakTipi,"")="KASA","Kasa/Banka",Nz(s.KaynakTipi,"")="ALIMSATIM","Alım/Satım",True,"Manuel") AS Kaynak, s.Tarih AS TarihHam
FROM ((tbl_StokHareket AS s INNER JOIN tbl_Urun AS u ON s.UrunID=u.UrunID) LEFT JOIN tbl_Musteri AS m ON s.MusteriID=m.MusteriID) LEFT JOIN tbl_Parti AS p ON s.PartiNo=p.PartiNo
WHERE s.IptalMi=False;